package com.turboio.addon;
import java.io.*;import java.nio.file.*;import java.time.*;import java.util.*;
public final class MaterialVisibilityTest {
 static int checks;static void yes(boolean v){checks++;if(!v)throw new AssertionError("Material visibility "+checks);}
 public static void main(String[] args)throws Exception{File root=new File(args[0]);String account=OfficialLifelogDiscoveryTest.ACCOUNT.binding,day=OfficialLifelogDiscoveryTest.DAY.date,zone=OfficialLifelogDiscoveryTest.DAY.timezone;OfficialLifelogDiscoveryTest.Wire wire=new OfficialLifelogDiscoveryTest.Wire();OfficialLifelogDiscovery.Snapshot fresh=OfficialLifelogDiscoveryTest.read(wire);MaterialCatalog catalog;
  try(MaterialLocalLibrary library=new MaterialLocalLibrary(root,account)){library.recordRead(day,zone,fresh.sources,System.currentTimeMillis(),()->account);catalog=MaterialCatalog.merge(MaterialCatalog.empty(account,ZoneId.of(zone)),library.snapshot());}String id=catalog.entries.get(0).id;Path retained=root.toPath().resolve("material-accounts/"+account+"/local-library/state.json");byte[] before=Files.readAllBytes(retained);
  try(MaterialVisibility visibility=new MaterialVisibility(root,account)){visibility.readDay(day,zone,fresh,()->account);yes(MaterialCatalog.visible(catalog,visibility).on(LocalDate.parse(day)).size()==1);OfficialLifelogDiscoveryTest.Wire empty=new OfficialLifelogDiscoveryTest.Wire();OfficialLifelogInventoryTest.data(empty.listing).put("events",new ArrayList<>());visibility.readDay(day,zone,OfficialLifelogDiscoveryTest.read(empty),()->account);yes(MaterialCatalog.visible(catalog,visibility).on(LocalDate.parse(day)).isEmpty());yes(Arrays.equals(before,Files.readAllBytes(retained)));visibility.readDay(day,zone,fresh,()->account);yes(MaterialCatalog.visible(catalog,visibility).on(LocalDate.parse(day)).size()==1);}
  try(MaterialVisibility visibility=new MaterialVisibility(root,account)){yes(!MaterialCatalog.visible(catalog,visibility).entries.isEmpty());boolean changed=false;try{visibility.readDay(day,zone,fresh,()->"b".repeat(64));}catch(IllegalArgumentException expected){changed=true;}yes(changed);}
  try(MaterialVisibility other=new MaterialVisibility(root,"b".repeat(64))){boolean refused=false;try{MaterialCatalog.visible(catalog,other);}catch(IllegalArgumentException expected){refused=true;}yes(refused);}yes(Arrays.equals(before,Files.readAllBytes(retained)));System.out.println("Material visibility: "+checks+" checks passed");
 }
}
